mapper.select:
SELECT u.id, u.username, u.password, u.real_name, u.user_type, u.phone, u.email, u.avatar, u.status, u.last_login, u.create_time, u.update_time, u.deleted FROM sys_user u WHERE u.deleted = 0
AND u.username LIKE CONCAT('%', #{query.username}, '%')
AND u.real_name LIKE CONCAT('%', #{query.realName}, '%')
AND u.user_type = #{query.userType}
AND u.status = #{query.status}
ORDER BY u.create_time DESC
